mapper.update:
UPDATE stock
SET available_stock = available_stock - #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE concert_id = #{concertId}
  AND grade_id = #{gradeId}
  AND available_stock >= #{quantity}
  AND version = #{version}

UPDATE stock
SET available_stock = available_stock + #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE concert_id = #{concertId}
  AND grade_id = #{gradeId}
